```javascript
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, BoxGeometry, DirectionalLight } = THREE;

  const root = new Group();

  // Grid layout constants
  const gridW = 5.5;
  const gridH = 3.5;
  const gutter = 0.25;
  const depth = 0.06;
  const pad = 0.5;

  const domW = 3.25;
  const domH = 3.5;
  const secW = 2.0;
  const secH = 1.625;

  const gridX = -gridW / 2;
  const gridY = gridH / 2;

  const timelines = [];
  const materials = [];

  // Backdrop plane (dark stage)
  const backGeo = new BoxGeometry(7, 6, 0.01);
  const backMat = new MeshBasicNodeMaterial({ color: 0x0b0b10 });
  const backdrop = new Mesh(backGeo, backMat);
  backdrop.position.z = -2.5;
  root.add(backdrop);
  materials.push(backMat);

  // Node-local rim light (accent color, ≤1.5 intensity)
  const rimLight = new DirectionalLight(0xff2a38, 0.8);
  rimLight.position.set(-2, 1.5, -1.5);
  root.add(rimLight);

  // Cell groups
  const cells = [];

  // Dominant cell (left, spans both rows)
  const domCell = createCell(domW, domH, gridX + domW / 2, 0);
  root.add(domCell);
  cells.push({ group: domCell, w: domW, h: domH });

  // Secondary cell 1 (top-right)
  const sec1Cell = createCell(
    secW,
    secH,
    gridX + domW + gutter + secW / 2,
    gridY - secH / 2
  );
  root.add(sec1Cell);
  cells.push({ group: sec1Cell, w: secW, h: secH });

  // Secondary cell 2 (bottom-right)
  const sec2Cell = createCell(
    secW,
    secH,
    gridX + domW + gutter + secW / 2,
    gridY - secH - gutter - secH / 2
  );
  root.add(sec2Cell);
  cells.push({ group: sec2Cell, w: secW, h: secH });

  // Add text elements
  addTextContent(gridX, gridY);

  // Apply entrance animation (stagger-cards fade-up)
  applyEntranceAnimation(cells);

  // Setup hover interactions (press-down, weighted-settle)
  setupHoverInteractions(cells);

  // Cleanup
  root.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    materials.forEach(mat => mat.dispose());
  };

  return root;

  // ===== Helper Functions =====

  function createCell(w, h, x, y) {
    const group = new Group();
    group.position.set(x, y, 0);

    // Cell surface mesh (shallow extruded slab)
    const cellGeo = new BoxGeometry(w, h, depth);
    const cellMat = new MeshStandardNodeMaterial({
      color: 0x14141a,
      roughness: 0.5,
      metalness: 0.45,
      clearcoat: 0.2,
    });
    const cellMesh = new Mesh(cellGeo, cellMat);
    group.add(cellMesh);
    materials.push(cellMat);

    // Accent tick bar (top-left, emissive signal red)
    const tickGeo = new BoxGeometry(0.4, 0.05, depth * 2);
    const tickMat = new MeshBasicNodeMaterial({
      color: 0xff2a38,
      emissive: 0xff2a38,
      emissiveIntensity: 1.3,
    });
    const tickMesh = new Mesh(tickGeo, tickMat);
    tickMesh.position.set(
      -w / 2 + pad + 0.2,
      h / 2 - pad - 0.025,
      depth * 0.75
    );
    group.add(tickMesh);
    materials.push(tickMat);

    return group;
  }

  function addTextContent(x0, y0) {
    // Header caption
    const header = ctx.fontAtlas.createText('ATELIER METRICS / Q2 2026', {
      fontSize: 18,
      color: '#e8ecf2',
      align: 'left',
      letterSpacingPx: 3.2,
    });
    header.position.set(x0, y0 + 0.5, 0.1);
    root.add(header);

    // Dominant cell: value + label
    const domValue = ctx.fontAtlas.createText('0.002 mm', {
      fontSize: 124,
      color: '#e8ecf2',
      align: 'center',
    });
    domValue.position.set(x0 + domW / 2, 0.5, 0.1);
    root.add(domValue);

    const domLabel = ctx.fontAtlas.createText('Case tolerance, CNC pass', {
      fontSize: 18,
      color: '#e8ecf2',
      align: 'center',
    });
    domLabel.position.set(x0 + domW / 2, -0.3, 0.1);
    root.add(domLabel);

    // Secondary cell 1: value + label
    const sec1X = x0 + domW + gutter + secW / 2;
    const sec1Y = y0 - secH / 2;

    const sec1Value = ctx.fontAtlas.createText('38 h', {
      fontSize: 68,
      color: '#e8ecf2',
      align: 'center',
    });
    sec1Value.position.set(sec1X, sec1Y + 0.25, 0.1);
    root.add(sec1Value);

    const sec1Label = ctx.fontAtlas.createText('Power reserve, NA-01', {
      fontSize: 18,
      color: '#e8ecf2',
      align: 'center',
    });
    sec1Label.position.set(sec1X, sec1Y - 0.25, 0.1);
    root.add(sec1Label);

    // Secondary cell 2: value + label
    const sec2Y = y0 - secH - gutter - secH / 2;

    const sec2Value = ctx.fontAtlas.createText('214', {
      fontSize: 68,
      color: '#e8ecf2',
      align: 'center',
    });
    sec2Value.position.set(sec1X, sec2Y + 0.25, 0.1);
    root.add(sec2Value);

    const sec2Label = ctx.fontAtlas.createText('Components per calibre', {
      fontSize: 18,
      color: '#e8ecf2',
      align: 'center',
    });
    sec2Label.position.set(sec1X, sec2Y - 0.25, 0.1);
    root.add(sec2Label);
  }

  function applyEntranceAnimation(cellsData) {
    const duration = 0.5;
    const stagger = 0.08;

    cellsData.forEach((cellData, index) => {
      const cell = cellData.group;
      const originalY = cell.position.y;

      // Set initial offset
      cell.position.y += 0.2;

      // Animate entrance: fade-up with y translation
      const tl = gsap.timeline();
      tl.to(
        cell.position,
        {
          y: originalY,
          duration,
          ease: 'power2.out',
        },
        index * stagger
      );

      timelines.push(tl);
    });
  }

  function setupHoverInteractions(cellsData) {
    cellsData.forEach(cellData => {
      const cell = cellData.group;

      // Hover enter: press-down scale
      cell.userData.onPointerEnter = () => {
        const tl = gsap.to(cell.scale, {
          x: 0.97,
          y: 0.97,
          z: 0.97,
          duration: 0.12,
          ease: 'back.out',
        });
        timelines.push(tl);
      };

      // Hover leave: weighted-settle back to 1.0
      cell.userData.onPointerLeave = () => {
        const tl = gsap.to(cell.scale, {
          x: 1,
          y: 1,
          z: 1,
          duration: 0.9,
          ease: 'power4.out',
        });
        timelines.push(tl);
      };
    });
  }
}
